#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9
ENV_FILE="${REPPIT_SETUP_ENV:-$HOME/.local/share/reppit-setup/supabase.env}"
mkdir -p "$(dirname "$ENV_FILE")"

banner "reppit production setup"

stage "Create the Supabase project"
say "This creates a separate database. It will not touch the existing pitch project."
open_url "https://supabase.com/dashboard/new/iiooiqfcrhduakfdrdib"
step "Use project name: reppit."
step "Generate a strong database password and save it in your password manager."
step "Choose Sydney if it is available. Keep Data API and automatic RLS enabled."
step "Click Create new project and wait until the project overview is ready."
pause "Project ready? Press Enter."
step "Copy the project reference from the dashboard URL: /project/PROJECT_REF."
ask SUPABASE_PROJECT_REF "Project reference:"
write_env SUPABASE_PROJECT_REF "$SUPABASE_PROJECT_REF"

stage "Copy the API keys"
say "The publishable key is used by the browser. The secret key stays server-side."
open_url "https://supabase.com/dashboard/project/$SUPABASE_PROJECT_REF/settings/api-keys"
step "Copy the Project URL."
ask NEXT_PUBLIC_SUPABASE_URL "Project URL:"
step "Copy the publishable key."
ask NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY "Publishable key:"
step "Reveal and copy the secret key. Input stays hidden here."
ask_secret SUPABASE_SECRET_KEY "Secret key:"
write_env NEXT_PUBLIC_SUPABASE_URL "$NEXT_PUBLIC_SUPABASE_URL"
write_env NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY "$NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY"
write_env SUPABASE_SECRET_KEY "$SUPABASE_SECRET_KEY"
write_env EMBEDDING_PROVIDER "supabase"
write_env EMBEDDING_FUNCTION_URL "$NEXT_PUBLIC_SUPABASE_URL/functions/v1/embed"
EMBEDDING_FUNCTION_KEY=$(_existing EMBEDDING_FUNCTION_KEY || openssl rand -hex 32)
write_env EMBEDDING_FUNCTION_KEY "$EMBEDDING_FUNCTION_KEY"
write_env DATABASE_POOL_MAX "1"

stage "Copy the database connections"
open_url "https://supabase.com/dashboard/project/$SUPABASE_PROJECT_REF"
step "Click Connect, then choose the Transaction pooler connection string on port 6543."
step "Replace [YOUR-PASSWORD] with the database password you saved."
step "Add sslmode=require if it is not already present. Copy the full URI. Input stays hidden here."
ask_secret DATABASE_URL "Serverless DATABASE_URL:"
write_env DATABASE_URL "$DATABASE_URL"
step "Now copy the Direct connection or Session pooler URI on port 5432 and require TLS."
ask_secret DIRECT_URL "Migration DIRECT_URL:"
write_env DIRECT_URL "$DIRECT_URL"

stage "Sign in to Vercel"
say "The Vercel project already exists. This authorizes the local deploy command."
if vercel whoami >/dev/null 2>&1; then
  say "Vercel CLI is already signed in."
else
  step "Complete the Vercel sign-in page opened by the next command, then return here."
  vercel login
fi

stage "Buy and connect reppit.dev"
say "The current first-year quote is checked again before the purchase. The approved ceiling is USD 13."
DOMAIN_QUOTE=$(curl --fail-with-body --silent --show-error https://api.vercel.com/v1/registrar/domains/search \
  --header 'Content-Type: application/json' --data '{"domains":["reppit.dev"]}')
DOMAIN_AVAILABLE=$(printf '%s' "$DOMAIN_QUOTE" | python3 -c 'import json,sys; print(str(json.load(sys.stdin)["results"][0]["available"]).lower())')
DOMAIN_PRICE=$(printf '%s' "$DOMAIN_QUOTE" | python3 -c 'import json,sys; print(json.load(sys.stdin)["results"][0].get("price", ""))')
if [[ "$DOMAIN_AVAILABLE" != "true" ]] || ! awk -v price="$DOMAIN_PRICE" 'BEGIN { exit !(price > 0 && price <= 13) }'; then
  warn "reppit.dev is unavailable or the first-year quote is above USD 13. Nothing was purchased."
  SKIPPED+=("domain purchase: quote changed")
elif confirm "Buy reppit.dev for USD $DOMAIN_PRICE for the first year with auto-renew (review the renewal price shown by Vercel), then connect the web and API projects?"; then
  vercel domains buy reppit.dev --scope jyothiprakash21au-6884s-projects
  vercel domains add reppit.dev reppit --scope jyothiprakash21au-6884s-projects
  vercel domains add api.reppit.dev reppit-api --scope jyothiprakash21au-6884s-projects
else
  SKIPPED+=("domain purchase: reppit.dev")
fi

stage "Connect Supabase to Vercel"
say "This sends the project keys straight from Supabase to the empty reppit Vercel project."
open_url "https://supabase.com/dashboard/project/$SUPABASE_PROJECT_REF/settings/integrations"
step "Choose the Vercel integration and connect your Vercel account."
step "Select the reppit project and enable Production, Preview, and Development environments."
pause "Integration connected? Press Enter."

stage "Secure the embedding function"
say "The embedding endpoint uses a dedicated server-side key. It never accepts the browser publishable key."
if ! npx --yes supabase@2.122.0 projects list --output table >/dev/null 2>&1; then
  step "Complete the Supabase CLI browser login opened by the next command."
  npx --yes supabase@2.122.0 login --agent no --output-format text
fi
npx --yes supabase@2.122.0 secrets set "REPPIT_EMBED_KEY=$EMBEDDING_FUNCTION_KEY" --project-ref "$SUPABASE_PROJECT_REF"
npx --yes supabase@2.122.0 functions deploy embed --project-ref "$SUPABASE_PROJECT_REF" --workdir packages/db
say "Embedding function secret set and function deployed."

stage "Enable the nightly index refresh"
say "The workflow reads public GitHub data and refreshes repo signals and skills each night."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Create a fine-grained token with read access to public repositories."
ask_secret INDEX_GITHUB_TOKEN "GitHub token:"
set_secret DATABASE_URL "$DATABASE_URL"
set_secret INDEX_GITHUB_TOKEN "$INDEX_GITHUB_TOKEN"
set_secret EMBEDDING_FUNCTION_URL "$EMBEDDING_FUNCTION_URL"
set_secret EMBEDDING_FUNCTION_KEY "$EMBEDDING_FUNCTION_KEY"

stage "Sign in to npm"
say "The MCP client is published first, then the five native CLI packages, then the reppit launcher."
if npm whoami >/dev/null 2>&1; then
  say "npm is already signed in."
else
  step "Complete the npm sign-in page opened by the next command, then return here."
  npm login
fi

finish
}

run_wizard "$@"; exit
